style.img:
/背景图使用，
     站主要求首页"单纯一点"——只有星星和星云，不要成片的文字和线。 */
  .mz-line{fill:none;stroke:#9fc4ff;stroke-width:1.15;stroke-opacity:.10;stroke-linecap:round}
  /* 这里的 .mz-name 是**背景图里**的标签，必须彻底隐藏。
     之前选择器写成 ".mansion .mz-name"，但 SVG 里生成的  是
     直接挂在根上的，没有 .mansion 祖先 —— 选择器永远匹配不上，
     于是 fill 回落到默认值、标签全亮着显示，画面才那么杂。
     现在改成直接选中 .mz-name，并且明确 display:none。
     （可交互的星宿图层在 assets/mansion-layer.js 里，那套是另一份样式。） */
  .mz-name{display:none}
  .halo{fill:url(#soft);opacity:.26}
  .flare{stroke:#ffffff;stroke-width:.8;stroke-opacity:.22;stroke-linecap:round}
  .tw{animation:tw 5s ease-in-out infinite alternate}
  @keyframes tw{from{opacity:.32}to{opacity:1}}
